  async function compressImage(file){
    if(!file.type?.startsWith('image/')||file.size<900000)return file;
    try{
      const img=await new Promise((resolve,reject)=>{const el=new Image(),u=URL.createObjectURL(file);el.onload=()=>{URL.revokeObjectURL(u);resolve(el)};el.onerror=e=>{URL.revokeObjectURL(u);reject(e)};el.src=u;});
      const max=1600,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*scale);c.height=Math.round(img.naturalHeight*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);
      const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.78));if(!blob)return file;return new File([blob],file.name.replace(/\.[^.]+$/,'.jpg'),{type:'image/jpeg'});
    }catch(_){return file;}
  }
  async function addActionEvidence(files){
    if(!draftAction||!files?.length)return;
    const current=draftAction.attachments||[];if(current.length+files.length>5){alert('Maximum 5 evidence attachments per action.');return;}
    $('actionSaveMessage').textContent='Uploading evidence…';
    try{
      for(const original of files){const file=await compressImage(original);if(file.size>3000000)throw new Error(`${file.name} is too large. Please keep each file below 3 MB.`);const out=await Cloud.uploadActionEvidence(draftAction.id,file);if(!out?.file)throw new Error(`Could not upload ${file.name}`);draftAction.attachments.push(out.file);}
      renderActionAttachments();$('actionFiles').value='';$('actionSaveMessage').textContent='Evidence uploaded. Save the action to confirm the update.';
    }catch(e){$('actionSaveMessage').textContent='Upload failed: '+e.message;alert('Evidence upload failed: '+e.message);}
  }
  async function downloadActionEvidence(index){if(!draftAction?.attachments?.[index])return;try{const meta=draftAction.attachments[index],out=await Cloud.getActionEvidence(draftAction.id,meta),data=out?.file?.dataUrl||meta.dataUrl;if(!data)throw new Error('Evidence data is unavailable.');const a=document.createElement('a');a.href=data;a.download=meta.name||'evidence';document.body.appendChild(a);a.click();a.remove();}catch(e){alert('Could not open evidence: '+e.message);}}
  async function removeActionEvidence(index){if(!draftAction?.attachments?.[index])return;if(!confirm('Remove this evidence attachment?'))return;const meta=draftAction.attachments[index];try{await Cloud.deleteActionEvidence(draftAction.id,meta);draftAction.attachments.splice(index,1);let record=collectActionForm();record.attachments=[...(draftAction.attachments||[])];const out=await Cloud.saveAction(record),saved=out?.record||record,i=actionRecords.findIndex(x=>x.id===saved.id);if(i>=0)actionRecords[i]=saved;else actionRecords.push(saved);draftAction=JSON.parse(JSON.stringify(saved));renderActionAttachments();renderActionHistory();renderActions();$('actionSaveMessage').textContent='Evidence removed and action updated.';}catch(e){alert('Could not remove evidence: '+e.message);}}
  async function saveActionFromModal(forceClosed=false){
    if(!draftAction)return;let record=collectActionForm();if(forceClosed){record.status='Closed';$('actionStatus').value='Closed';}
    if(record.status==='Closed'&&!record.adminResponse){alert('Add the Action Taken / Response before closing the action.');$('actionResponse').focus();return;}
    if(record.status==='Closed'&&!(record.attachments||[]).length){alert('Attach at least one close-out evidence file before closing the action.');return;}
    const now=new Date().toISOString(),previous=actionRecords.find(x=>x.id===record.id),prevStatus=previous?.status||draftAction.status||'Open';
    if(record.status==='Closed'&&!record.closedAt)record.closedAt=now;else if(record.status!=='Closed')record.closedAt=null;
    const history=[...(record.history||[])];history.push({time:now,status:record.status,note:record.adminResponse||record.closureComment||`Status updated from ${prevStatus} to ${record.status}`});record.history=history;
    $('actionSaveMessage').textContent='Saving action…';
    try{const out=await Cloud.saveAction(record),saved=out?.record||record,i=actionRecords.findIndex(x=>x.id===saved.id);if(i>=0)actionRecords[i]=saved;else actionRecords.push(saved);draftAction=JSON.parse(JSON.stringify(saved));$('actionSaveMessage').textContent='Saved centrally.';renderActionAttachments();renderActionHistory();renderActions();}
    catch(e){$('actionSaveMessage').textContent='Save failed: '+e.message;alert('Could not save action: '+e.message);}
  }

  const htmlEsc=esc;
  function reportCampaignName(campaignName){return campaignName&&campaignName!=='All'?campaignName:(filters.campaign==='All'?currentCampaign():filters.campaign);}
  function reportModel(campaignName=null){
    const old={...filters},campaign=reportCampaignName(campaignName);
    filters={campaign,role:'All',division:'All',factor:'All',language:'All',period:'All'};
    try{
      const rs=filtered(),all=answers(rs),p=parts(all.map(x=>x.v)),factors=factorScores(rs),roles=roleScores(),divs=[...new Set(rs.map(r=>r.division||'Not specified'))].map(name=>{const x=rs.filter(r=>(r.division||'Not specified')===name),v=answers(x).map(a=>a.v);return{name,responses:x.length,score:v.length?pct(v,n=>n>=4,1):null};}).sort((a,b)=>(b.score??-1)-(a.score??-1)),qs=questionGroups().map(g=>{const vals=g.entries.map(e=>e.v).filter(Number.isFinite),pp=parts(vals);return{key:g.key,roleId:g.role,role:rlabel(g.role),factorId:g.factor,factor:factorLabel(g.factor),question:qtitle(g),responses:vals.length,favourable:pp.good,neutral:pp.neutral,unfavourable:pp.bad,average:mean(vals),comments:g.entries.filter(e=>(e.a.comment||'').trim()).length};}),comments=commentsList(rs),actions=managedActions(rs);
      return{campaign,rs,p,idx:mean(all.map(x=>x.v)),factors,roles,divs,qs,comments,actions};
    }finally{filters=old;}
  }
  function detailedReportModel(campaignName=null){
    const campaign=reportCampaignName(campaignName),base=reportModel(campaign),old={...filters};
    filters={campaign,role:'All',division:'All',factor:'All',language:'All',period:'All'};
    try{
      const rs=filtered(),groups=questionGroups(),allDivisions=[...new Set(rs.map(r=>r.division||'Not specified'))].sort();
      const factorDetails=Object.keys(config?.factors||{}).map((id,index)=>{
        const summary=base.factors.find(x=>x.id===id)||{id,label:factorLabel(id),score:null,bad:null,neutral:null,n:0,comments:0};
        const questions=groups.filter(g=>g.factor===id).map(g=>{const vals=g.entries.map(e=>e.v).filter(Number.isFinite),pp=parts(vals),comments=g.entries.filter(e=>(e.a.comment||'').trim()).map(e=>({text:e.a.comment,role:role(e.r.role),division:e.r.division||'',rating:e.a.value,time:e.r.timestamp}));return{key:g.key,roleId:g.role,role:rlabel(g.role),text:qtitle(g),responses:vals.length,favourable:pp.good,neutral:pp.neutral,unfavourable:pp.bad,average:mean(vals),comments};}).filter(q=>q.responses);
        const roles=(config?.roles||[]).filter(r=>r.enabled!==false).map(rr=>{const rrs=rs.filter(x=>role(x.role)===rr.id),vals=answers(rrs,id).map(x=>x.v);return{id:rr.id,label:rlabel(rr.id),responses:rrs.length,score:vals.length?pct(vals,v=>v>=4,1):null};});
        const divisions=allDivisions.map(name=>{const drs=rs.filter(r=>(r.division||'Not specified')===name),vals=answers(drs,id).map(x=>x.v);return{name,responses:drs.length,score:vals.length?pct(vals,v=>v>=4,1):null};}).filter(x=>x.score!=null).sort((a,b)=>(b.score??-1)-(a.score??-1));
        const strongest=[...questions].sort((a,b)=>b.favourable-a.favourable)[0]||null,concern=[...questions].sort((a,b)=>b.unfavourable-a.unfavourable)[0]||null;
        const factorComments=commentsList(rs).filter(c=>c.factor===id);
        const action=factorActions[id]||{title:summary.label,action:`Review the ${summary.label} findings with the workforce and implement a targeted improvement plan.`,owner:'HSE Manager'};
        return{index:index+1,id,label:summary.label,summary,questions,roles,divisions,strongest,concern,comments:factorComments,action};
      });
      const allQuestions=factorDetails.flatMap(f=>f.questions.map(q=>({...q,factor:f.label,factorId:f.id})));
      const topStrengths=[...allQuestions].sort((a,b)=>b.favourable-a.favourable).slice(0,3),topConcerns=[...allQuestions].sort((a,b)=>b.unfavourable-a.unfavourable).slice(0,3);
      return{...base,factorDetails,topStrengths,topConcerns};
    }finally{filters=old;}
  }
  function download(name,content,type){const blob=new Blob([content],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
  async function asDataUrl(src){if(!src)return'';if(String(src).startsWith('data:'))return src;try{const r=await fetch(src,{cache:'no-store'});if(!r.ok)return'';const b=await r.blob();return await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(b)});}catch(_){return'';}}
  async function reportLogos(){const list=(config?.logos||[]).filter(x=>x.enabled!==false&&x.src);const out=[];for(const x of list){const src=await asDataUrl(x.src);if(src)out.push({name:x.name||'',src});}return out;}
  function safeFilePart(x){return String(x||'report').replace(/[^a-z0-9]+/gi,'_').replace(/^_+|_+$/g,'').slice(0,70)||'report';}
  function barReport(label,value,color='#087a4a'){const has=value!=null&&Number.isFinite(Number(value)),v=has?Math.max(0,Math.min(100,Number(value))):0;return `<table class="chartbar" cellspacing="0" cellpadding="0"><tr><td class="chartlabel">${htmlEsc(label)}</td><td class="charttrack"><table cellspacing="0" cellpadding="0" width="100%"><tr><td bgcolor="${color}" width="${v}%" style="height:14px"></td><td bgcolor="#edf2f4" width="${100-v}%"></td></tr></table></td><td class="chartvalue">${has?Number(value).toFixed(1)+'%':'—'}</td></tr></table>`;}
  function stackedReport(g,n,b){return `<table cellspacing="0" cellpadding="0" width="100%" style="height:15px"><tr><td bgcolor="#8fc98d" width="${g}%"></td><td bgcolor="#f0d08c" width="${n}%"></td><td bgcolor="#df9b96" width="${b}%"></td></tr></table>`;}
  function detailedStack(b,n,g){return `<table class="sentiment" cellspacing="0" cellpadding="0" width="100%"><tr><td bgcolor="#df9b96" width="${b}%">${b>=9?b.toFixed(1)+'%':''}</td><td bgcolor="#f0d08c" width="${n}%">${n>=9?n.toFixed(1)+'%':''}</td><td bgcolor="#a6d39d" width="${g}%">${g>=9?g.toFixed(1)+'%':''}</td></tr></table>`;}
  function reportActionRows(actions){return actions.map((a,i)=>`<tr><td>${i+1}</td><td><b>${htmlEsc(a.priority||'')}</b></td><td>${htmlEsc(a.title||'')}</td><td>${htmlEsc(a.evidence||'')}</td><td>${htmlEsc(a.recommendedAction||a.action||'')}</td><td>${htmlEsc(a.owner||'')}</td><td>${htmlEsc(a.target||'')}</td><td>${htmlEsc(a.status||'Open')}</td><td>${htmlEsc(a.adminResponse||'')}</td><td>${htmlEsc(a.closureComment||'')}</td><td>${htmlEsc((a.attachments||[]).map(x=>x.name).join('; '))}</td><td>${a.closedAt?new Date(a.closedAt).toLocaleDateString():''}</td></tr>`).join('');}
  function reportInsights(m){const good=[...m.factors].filter(x=>x.score!=null).sort((a,b)=>b.score-a.score)[0],low=[...m.factors].filter(x=>x.score!=null).sort((a,b)=>a.score-b.score)[0],open=m.actions.filter(a=>a.status!=='Closed').length,closed=m.actions.filter(a=>a.status==='Closed').length;return{good,low,open,closed};}
  function performanceText(score){if(score==null)return'No data';const green=Number(config?.performanceThresholds?.green??75),amber=Number(config?.performanceThresholds?.amber??60);return score>=green?'Strong / favourable':score>=amber?'Needs attention':'Priority concern';}
